// Renders the Roguelike info page from /roguelike/catalog.json (generated by tools/roguelike/refresh.sh).
(function () {
    "use strict";
    var BOON_GROUPS = [
        ["dungeon", "Dungeon boons"], ["offense", "Offense"], ["defense", "Defense"], ["sustain", "Sustain"],
        ["resource", "Resources"], ["utility", "Utility & movement"], ["pet", "Pets"], ["wild", "Wild Cards & Relics"]
    ];
    var CURSE_GROUPS = [
        ["affix", "Dungeon affixes", "Make every enemy in your dungeon stronger, for the whole group."],
        ["hazard", "Hazards", "Personal pressure in combat. Only the snail can kill you."],
        ["dungeon", "Dungeon curses", ""],
        ["character", "Character curses", "Weaken you or change how you play."],
        ["pact", "Pacts", "A strong upside tied to a downside."],
        ["trial", "Trials", "A curse until you complete the dungeon goal, then a boon."]
    ];
    var BADGE = { wildcard: "wild", relic: "wild", pact: "pact", trial: "trial", affix: "affix" };

    function el(tag, cls, text) {
        var e = document.createElement(tag);
        if (cls) e.className = cls;
        if (text != null) e.textContent = text;
        return e;
    }
    function iconUrl(icon) {
        return "/roguelike/icons/" + String(icon || "inv_misc_questionmark").toLowerCase() + ".jpg";
    }
    function card(e) {
        var c = el("div", "card " + e.kind);
        c.dataset.search = (e.name + " " + e.desc + " " + e.typeName + " " + (e.tags || []).join(" ")).toLowerCase();
        var img = el("img");
        img.src = iconUrl(e.icon);
        img.alt = "";
        img.loading = "lazy";
        img.onerror = function () { this.onerror = null; this.src = iconUrl(null); };
        c.appendChild(img);
        var body = el("div");
        var name = el("div", "name", e.name);
        (e.tags || []).forEach(function (t) {
            name.appendChild(el("span", "badge " + (t.toLowerCase() === "lethal" ? "lethal" : "muted"), t));
        });
        if (BADGE[e.type]) name.appendChild(el("span", "badge " + BADGE[e.type], e.typeName));
        if (e.requires === "mobileCast") name.appendChild(el("span", "badge muted", "needs new launcher"));
        body.appendChild(name);
        body.appendChild(el("div", "desc", e.desc));
        c.appendChild(body);
        return c;
    }
    function curseGroup(e) {
        if (e.type === "affix" || e.type === "pact" || e.type === "trial") return e.type;
        if (e.cat === "hazard" || e.cat === "dungeon") return e.cat;
        return "character";
    }
    function render(target, list, groups, keyOf) {
        target.textContent = "";
        groups.forEach(function (g) {
            var items = list.filter(function (e) { return keyOf(e) === g[0]; });
            if (!items.length) return;
            var wrap = el("div", "group");
            var h = el("h3", "group-title", g[1] + " ");
            h.appendChild(el("small", null, "(" + items.length + ")" + (g[2] ? " " + g[2] : "")));
            wrap.appendChild(h);
            var cards = el("div", "cards");
            items.sort(function (a, b) { return a.name.localeCompare(b.name); }).forEach(function (e) { cards.appendChild(card(e)); });
            wrap.appendChild(cards);
            target.appendChild(wrap);
        });
        var known = groups.map(function (g) { return g[0]; });
        var rest = list.filter(function (e) { return known.indexOf(keyOf(e)) < 0; });
        if (rest.length) {
            var w = el("div", "group");
            w.appendChild(el("h3", "group-title", "Other"));
            var cs = el("div", "cards");
            rest.forEach(function (e) { cs.appendChild(card(e)); });
            w.appendChild(cs);
            target.appendChild(w);
        }
    }
    function wireFilter(input, target) {
        input.addEventListener("input", function () {
            var q = input.value.trim().toLowerCase();
            target.querySelectorAll(".group").forEach(function (g) {
                var shown = 0;
                g.querySelectorAll(".card").forEach(function (c) {
                    var hit = !q || c.dataset.search.indexOf(q) >= 0;
                    c.style.display = hit ? "" : "none";
                    if (hit) shown++;
                });
                g.style.display = shown ? "" : "none";
            });
        });
    }
    function dungeons(list) {
        var t = document.getElementById("dungeons");
        t.textContent = "";
        var names = ["Classic", "The Burning Crusade", "Wrath of the Lich King"];
        var last = -1;
        list.forEach(function (d) {
            if (d.expansion !== last) {
                last = d.expansion;
                t.appendChild(el("div", "exp", names[d.expansion] || ("Expansion " + d.expansion)));
            }
            var row = el("div");
            row.appendChild(el("span", null, d.name));
            row.appendChild(el("span", "lv", d.min + "\u2013" + d.max));
            t.appendChild(row);
        });
    }
    function sliders(dials) {
        var max = dials.slotsMax || 8, offers = dials.offers || 3;
        var base = dials.rerollsBase != null ? dials.rerollsBase : 1;
        var per = dials.rerollsPerCurse != null ? dials.rerollsPerCurse : 1;
        function upd() {
            var b = +document.getElementById("boon-slider").value, c = +document.getElementById("curse-slider").value;
            document.getElementById("boon-val").textContent = b;
            document.getElementById("curse-val").textContent = c;
            document.getElementById("boon-text").textContent = b
                ? b + " row" + (b > 1 ? "s" : "") + " of " + offers + " boon cards: keep " + b + " boon" + (b > 1 ? "s" : "") + "."
                : "No boons.";
            document.getElementById("curse-text").textContent = (c
                ? c + " row" + (c > 1 ? "s" : "") + " of " + offers + " curse cards: keep " + c + " (curses, pacts, trials or affixes)."
                : "No curses.") + " Row re-rolls: " + (base + per * c) + ".";
        }
        ["boon-slider", "curse-slider"].forEach(function (id) {
            var s = document.getElementById(id);
            s.max = max;
            s.addEventListener("input", upd);
        });
        upd();
    }
    function setText(cls, v) {
        if (v == null) return;
        document.querySelectorAll("." + cls).forEach(function (n) { n.textContent = v; });
    }

    fetch("/roguelike/catalog.json", { credentials: "same-origin" })
        .then(function (r) { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
        .then(function (d) {
            var dials = d.dials || {};
            setText("js-slots", dials.slotsMax); setText("js-offers", dials.offers);
            setText("js-rr-base", dials.rerollsBase); setText("js-rr-curse", dials.rerollsPerCurse);
            setText("js-floor", dials.curseFloorPct);
            sliders(dials);
            dungeons(d.dungeons || []);
            document.getElementById("boon-count").textContent = d.boons.length;
            document.getElementById("curse-count").textContent = d.curses.length;
            var bg = document.getElementById("boon-groups"), cg = document.getElementById("curse-groups");
            render(bg, d.boons, BOON_GROUPS, function (e) { return e.cat; });
            render(cg, d.curses, CURSE_GROUPS, curseGroup);
            wireFilter(document.getElementById("boon-filter"), bg);
            wireFilter(document.getElementById("curse-filter"), cg);
            if (d.source && d.source.commit) {
                document.getElementById("source-line").textContent = "Boon and curse data generated from " +
                    d.source.repo + " (" + d.source.branch + " @ " + d.source.commit + ").";
            }
        })
        .catch(function (err) {
            ["boon-groups", "curse-groups"].forEach(function (id) {
                document.getElementById(id).textContent = "Could not load the catalog (" + err.message + ").";
            });
        });
})();
